38	    public CertificateRepository(JdbcTemplate jdbc) {
39	        this.jdbc = jdbc;
40	    }
41	
42	    /**
43	     * 获取仪器级互斥锁（须在事务内调用）：不存在锁行则插入，随后对该行 FOR UPDATE。
44	     */
45	    public void lockInstrument(String instrumentId) {
46	        try {
47	            jdbc.update("INSERT INTO instrument_lock (instrument_id, created_at) VALUES (?, ?)",
48	                    instrumentId, JdbcTimes.toDb(Instant.now()));
49	        } catch (DuplicateKeyException ignored) {
50	            // 锁行已存在，直接进入行锁等待
51	        }
52	        jdbc.queryForObject("SELECT instrument_id FROM instrument_lock WHERE instrument_id = ? FOR UPDATE",
53	                String.class, instrumentId);
54	    }
55	
56	    /**
57	     * 插入证书并返回生成的证书 ID。
58	     */
59	    public long insert(String instrumentId, Instant validFrom, Instant validTo,
60	                       java.math.BigDecimal a, java.math.BigDecimal b, Instant createdAt) {
61	        KeyHolder keyHolder = new GeneratedKeyHolder();
62	        jdbc.update(con -> {
